function buatTodoRepo() {
  const data = [];
  let nextId = 1;
  return {
    async tambah(t) { const baru = { id: nextId++, selesai: false, ...t }; data.push(baru); return { ...baru }; },
    async semuaMilik(p) { return data.filter((t) => t.penggunaId === p).map((t) => ({ ...t })); },
    async hapus(id) { data.splice(data.findIndex((x) => x.id === id), 1); },
  };
}
const repo = buatTodoRepo();
await repo.tambah({ penggunaId: 1, judul: 'Pertama' });
